package net.sonic0810.copperinferno.feature.emberswarm;

import net.minecraft.entity.EntityType;
import net.minecraft.entity.mob.MagmaCubeEntity;
import net.minecraft.world.World;

/**
 * A swarm magma cube. Behavior is pure vanilla magma cube, including the vanilla
 * size handling: {@code SlimeEntity.initialize(...)} rolls a random size (1/2/4) on
 * natural spawn, {@code setSize(int, boolean)} (public in 1.21.9, verified via
 * javap) rescales health/damage, and cubes split on death. Drops are in
 * {@code loot_table/entities/soot_cube.json}.
 * Generated by {@code devtools/gen/emberswarm_gen.py}.
 */
public class SootCubeEntity extends MagmaCubeEntity {
	public SootCubeEntity(EntityType<? extends MagmaCubeEntity> type, World world) {
		super(type, world);
	}
}
